query.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX db: <http://dbpedia.org/>

SELECT?capacity WHERE {
  { 
    dbr:FC_Porto dbo:ground?ground.
   ?ground dbo:populationTotal?capacity.
  } UNION {
    dbr:FC_Porto dbo:ground?ground.
   ?ground dbp:capacity?capacity.
  }
}

SELECT (CASE WHEN EXISTS { PREMIUM
  PREFIX res: <http://dbpedia.org/resource/> 
  PREFIX dbp: <http://dbpedia.org/property/> 
  SELECT DISTINCT?date WHERE { 
    res:Finland dbp:accessiondate?date 
  } 
  THEN '2023-01-01'
  ELSE 'Not a member'
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>

SELECT DISTINCT?uri WHERE {?x dbo:birthPlace?uri ; dbo:birthPlace?x.?x dbo:birthPlace dbr:Montenegro }

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX onto: <http://dbpedia.org/ontology/>

SELECT?uri?string WHERE { dbr:Abraham_Lincoln onto:spouse?spouse }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT?uri WHERE {?uri dbo:spouse dbo:Tom_Hanks }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX onto: <http://dbpedia.org/ontology/>
PREFIX prop: <http://dbpedia.org/property/>

SELECT DISTINCT?uri WHERE {
 ?uri rdf:type onto:Person
 ?uri prop:starring res:Tom_Cruise
  OPTIONAL {?uri rdfs:label?string FILTER ( lang(?string) = "en" ) }
}

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:Castles_in_the_United_States>

SELECT?uri WHERE {?uri dct:subject dbc:Castles_in_the_United_States }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns/>

SELECT DISTINCT?uri WHERE {
 ?uri rdf:type dbo:Person ;
         dct:subject dbc:Presidents_of_the_United_States ;
         dbo:birthDate?termEnd
  FILTER ( ( year(now()) - year(?termEnd) ) <= 20 )
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT dbo:dissolutionYear?date WHERE {?date a dbo:Company. FILTER (regex(str(?date), "De Beers")) }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT?uri 
WHERE { 
 ?uri rdf:type dbo:Book ; 
  dbo:numberOfPages?n 
} 
ORDER BY DESC(?n) 
OFFSET 0 
LIMIT 1
